#!/usr/bin/env bash
#
# hack/scripts/tests/kind-compatibility-test.sh
#
# Offline fixture tests for the Kind compatibility scripts generated by the
# rhai-kind-setup skill:
#
#   * hack/scripts/install-openshift-crds.sh — classification of existing
#     CRDs (absent, equivalent owned, unowned, other-owner, incompatible
#     owned, unreadable) and the all-set-before-write ordering of the
#     ownership preflight, using a command-capture kubectl double. No
#     cluster is contacted and no manifest generation runs here: the
#     manifests come from fixtures shaped like the verified generation
#     output (controller-gen regeneration and module resolution were
#     verified during generation and run at script runtime).
#   * hack/scripts/setup-service-certs.sh — baked-settings validation and
#     the cryptographic pair validation (key match, CA-trusted server
#     purpose, non-CA leaf, both Service DNS SANs, bounded SAN matching),
#     with locally generated certificates only.
#
# The scripts under test are sourced, never executed: their main() is
# guarded to run only when the file is executed directly, and every
# cluster-facing call (kubectl through the kctl wrapper, kind) is either
# not reached or replaced by a double that records its invocations, so a
# refusal can be proven to cause zero applies.
#
# Prerequisites: bash, jq, yq, openssl, and go (the installer's pinned yq
# runs through 'go run' using the shared Go module cache; the module is
# already pinned and cached by the script's settings). No network and no
# cluster are required.
#
# Usage: hack/scripts/tests/kind-compatibility-test.sh
# Exits nonzero if any check fails.

set -uo pipefail

TESTS_DIR="$(cd "$(dirname "$0")" && pwd)"
SCRIPTS_DIR="$(cd "${TESTS_DIR}/.." && pwd)"
INSTALLER="${SCRIPTS_DIR}/install-openshift-crds.sh"
CERT_SCRIPT="${SCRIPTS_DIR}/setup-service-certs.sh"

WORK="$(mktemp -d)" || { echo "cannot create a private test directory" >&2; exit 1; }
chmod 700 "$WORK"
cleanup() { rm -rf "$WORK"; }
trap cleanup EXIT

PASS=0
FAIL=0

ok() {
	PASS=$((PASS + 1))
	echo "  ok: $*"
}

bad() {
	FAIL=$((FAIL + 1))
	echo "  FAIL: $*" >&2
}

assert_eq() {
	# assert_eq <description> <expected> <actual>
	if [ "$2" = "$3" ]; then
		ok "$1"
	else
		bad "$1: expected [$2] but got [$3]"
	fi
}

assert_file_contains() {
	# assert_file_contains <description> <file> <fixed string>
	if grep -qF -- "$3" "$2" 2>/dev/null; then
		ok "$1"
	else
		bad "$1: [$2] does not contain [$3]"
	fi
}

log_count() {
	# log_count <log-file> <pattern>
	grep -c -- "$1" "$2" 2>/dev/null || true
}

for required_cmd in bash jq yq openssl go; do
	if ! command -v "$required_cmd" >/dev/null 2>&1; then
		echo "required command '$required_cmd' was not found in PATH" >&2
		exit 1
	fi
done

echo "== Static checks"

[ -x "$INSTALLER" ] && ok "install-openshift-crds.sh is executable" || bad "install-openshift-crds.sh is not executable"
[ -x "$CERT_SCRIPT" ] && ok "setup-service-certs.sh is executable" || bad "setup-service-certs.sh is not executable"

if bash -n "$INSTALLER" 2>"$WORK/installer.syntax"; then
	ok "install-openshift-crds.sh passes bash -n"
else
	bad "install-openshift-crds.sh fails bash -n: $(cat "$WORK/installer.syntax")"
fi
if bash -n "$CERT_SCRIPT" 2>"$WORK/certs.syntax"; then
	ok "setup-service-certs.sh passes bash -n"
else
	bad "setup-service-certs.sh fails bash -n: $(cat "$WORK/certs.syntax")"
fi

# '%%' never occurs in the script bodies, so its absence is an exact
# render-completeness check for the template substitution.
if grep -q '%%' "$INSTALLER"; then
	bad "install-openshift-crds.sh contains unresolved %% placeholders"
else
	ok "install-openshift-crds.sh has no unresolved %% placeholders"
fi
if grep -q '%%' "$CERT_SCRIPT"; then
	bad "setup-service-certs.sh contains unresolved %% placeholders"
else
	ok "setup-service-certs.sh has no unresolved %% placeholders"
fi

# ---------------------------------------------------------------------------
# Fixture manifests: shaped like the verified generation output (schema-
# poor controller-gen output) and the complete shipped manifests chosen
# during generation (schema-richer committed manifests). Only the three
# approved CRDs appear.
# ---------------------------------------------------------------------------

FIXGEN="${WORK}/fixtures/generated"
FIXMOD="${WORK}/fixtures/module"
FIXSCRATCH="${WORK}/fixtures/scratch"
mkdir -p "$FIXGEN/openshift-api_config_v1" "$FIXGEN/openshift-api_route_v1" "$FIXGEN/prometheus-monitoring_v1"
mkdir -p "$FIXMOD/config/v1/zz_generated.crd-manifests" "$FIXMOD/route/v1/zz_generated.crd-manifests"
mkdir -p "$FIXSCRATCH"

cat >"$FIXGEN/openshift-api_config_v1/config.openshift.io_apiservers.yaml" <<'YAML'
apiVersion: apiextensions.k8s.io/v1
kind: CustomResourceDefinition
metadata:
  name: apiservers.config.openshift.io
spec:
  group: config.openshift.io
  names:
    kind: APIServer
    listKind: APIServerList
    plural: apiservers
  scope: Cluster
  versions:
  - name: v1
    served: true
    storage: true
    schema:
      openAPIV3Schema:
        type: object
        properties:
          spec:
            type: object
            properties:
              audit:
                type: object
                properties:
                  profile:
                    type: string
YAML

cat >"$FIXMOD/config/v1/zz_generated.crd-manifests/0000_10_config-operator_01_apiservers-Default.crd.yaml" <<'YAML'
apiVersion: apiextensions.k8s.io/v1
kind: CustomResourceDefinition
metadata:
  name: apiservers.config.openshift.io
  annotations:
    api-approved.openshift.io: https://github.com/openshift/api/pull/470
    api.openshift.io/merged-by-featuregates: "true"
    release.openshift.io/feature-set: Default
spec:
  group: config.openshift.io
  names:
    kind: APIServer
    listKind: APIServerList
    plural: apiservers
    singular: apiserver
  scope: Cluster
  versions:
  - name: v1
    served: true
    storage: true
    subresources:
      status: {}
    schema:
      openAPIV3Schema:
        type: object
        required:
        - spec
        properties:
          spec:
            type: object
            required:
            - audit
            properties:
              audit:
                type: object
                required:
                - profile
                properties:
                  profile:
                    type: string
                    enum:
                    - Default
                    - WriteRequestBodies
              tlsSecurityProfile:
                type: object
                x-kubernetes-validations:
                - message: tlsAdherence may not be removed once set
                  rule: "has(oldSelf.tlsAdherence) ? has(self.tlsAdherence) : true"
YAML

cat >"$FIXGEN/openshift-api_route_v1/route.openshift.io_routes.yaml" <<'YAML'
apiVersion: apiextensions.k8s.io/v1
kind: CustomResourceDefinition
metadata:
  name: routes.route.openshift.io
spec:
  group: route.openshift.io
  names:
    kind: Route
    listKind: RouteList
    plural: routes
  scope: Namespaced
  versions:
  - name: v1
    served: true
    storage: true
    schema:
      openAPIV3Schema:
        type: object
        properties:
          spec:
            type: object
            properties:
              host:
                type: string
              tls:
                type: object
                properties:
                  termination:
                    type: string
YAML

cat >"$FIXMOD/route/v1/zz_generated.crd-manifests/routes.crd.yaml" <<'YAML'
apiVersion: apiextensions.k8s.io/v1
kind: CustomResourceDefinition
metadata:
  name: routes.route.openshift.io
  annotations:
    api-approved.openshift.io: https://github.com/openshift/api/pull/1228
    api.openshift.io/merged-by-featuregates: "true"
spec:
  group: route.openshift.io
  names:
    kind: Route
    listKind: RouteList
    plural: routes
    singular: route
  scope: Namespaced
  versions:
  - name: v1
    served: true
    storage: true
    schema:
      openAPIV3Schema:
        type: object
        properties:
          spec:
            type: object
            required:
            - host
            allOf:
            - anyOf:
              - properties:
                  path:
                    maxLength: 0
              - properties:
                  tls:
                    properties:
                      termination:
                        enum:
                        - passthrough
            properties:
              host:
                type: string
              path:
                type: string
              tls:
                type: object
                properties:
                  termination:
                    type: string
                    enum:
                    - edge
                    - passthrough
                    - reencrypt
YAML

cat >"$FIXGEN/prometheus-monitoring_v1/monitoring.coreos.com_servicemonitors.yaml" <<'YAML'
apiVersion: apiextensions.k8s.io/v1
kind: CustomResourceDefinition
metadata:
  name: servicemonitors.monitoring.coreos.com
spec:
  group: monitoring.coreos.com
  names:
    categories:
    - prometheus-operator
    kind: ServiceMonitor
    listKind: ServiceMonitorList
    plural: servicemonitors
    shortNames:
    - smon
  scope: Namespaced
  versions:
  - name: v1
    served: true
    storage: true
    schema:
      openAPIV3Schema:
        type: object
        properties:
          spec:
            type: object
            properties:
              selector:
                type: object
YAML

# Module-directory pointer files, as generate_crds would have written them.
printf '%s\n' "$FIXMOD" >"$FIXSCRATCH/moddir.openshift-api"
printf '%s\n' "$FIXMOD" >"$FIXSCRATCH/moddir.prometheus-monitoring"

# ---------------------------------------------------------------------------
# Drivers: child bash processes that source the script under test and call
# its helpers. The scripts' main() never runs when sourced.
# ---------------------------------------------------------------------------

# Classify one persisted CRD against one apply file.
cat >"$WORK/driver-classify.sh" <<'DRIVER'
# $1 = installer path, $2 = persisted CRD JSON, $3 = apply file
source "$1"
classify_existing_crd "$2" "$3"
printf 'DECISION=%s\n' "$CLASSIFY_DECISION"
DRIVER

# Validate the baked settings tables and prepare the annotated apply files.
cat >"$WORK/driver-prepare.sh" <<'DRIVER'
# $1 = installer path, $2 = fixture scratch dir, $3 = fixture generated dir
source "$1"
validate_baked_settings
SCRATCH_DIR="$2"
GENERATED_DIR="$3"
prepare_selected_manifests
echo "PREPARE-OK"
DRIVER

# Equivalence of two CRD documents through the installer's own canonical
# form (proves the annotation step changed nothing but metadata).
cat >"$WORK/driver-equivalence.sh" <<'DRIVER'
# $1 = installer path, $2 = file A, $3 = file B
source "$1"
if specs_equivalent "$2" "$3"; then
	echo "EQUIV-OK"
else
	echo "EQUIV-DIFF"
fi
DRIVER

# Preflight + apply with a command-capture kubectl double. The double
# serves fixture CRDs from a directory (one <name>.json per existing CRD,
# or an empty <name>.readfail marker for a CRD that is listed but cannot
# be read) and records every invocation, so a refusal can be proven to
# cause zero applies.
cat >"$WORK/driver-order.sh" <<'DRIVER'
# $1 = installer path, $2 = fixture scratch dir, $3 = existing-CRD dir,
# $4 = kctl invocation log
source "$1"
validate_baked_settings
SCRATCH_DIR="$2"
GENERATED_DIR="${2}/generated-unused"
mkdir -p "$GENERATED_DIR"
KCTL_LOG="$4"
EXISTING="$3"
kctl() {
	printf 'kctl: %s\n' "$*" >>"$KCTL_LOG"
	case "$1" in
	get)
		case "$2" in
		crds)
			names=""
			for f in "$EXISTING"/*.json "$EXISTING"/*.readfail; do
				[ -e "$f" ] || continue
				names="$names $(basename "$f" | sed -e 's/\.json$//' -e 's/\.readfail$//')"
			done
			printf '%s \n' "$names"
			;;
		crd)
			# $3 = CRD name
			if [ -e "$EXISTING/$3.readfail" ]; then
				echo "Error from server (Forbidden): customresourcedefinitions.apiextensions.k8s.io \"$3\" is forbidden" >&2
				return 1
			elif [ -s "$EXISTING/$3.json" ]; then
				cat "$EXISTING/$3.json"
			else
				echo "Error from server (NotFound): customresourcedefinitions.apiextensions.k8s.io \"$3\" not found" >&2
				return 1
			fi
			;;
		*)
			echo "unexpected kctl get invocation: $*" >&2
			return 1
			;;
		esac
		;;
	apply | wait)
		return 0
		;;
	*)
		echo "unexpected kctl invocation: $*" >&2
		return 1
		;;
	esac
}
if preflight_classify_selected && apply_selected; then
	echo "ORDER-OK"
fi
DRIVER

# Certificate-script helpers: settings validation and pair validation with
# locally generated material.
cat >"$WORK/driver-certs.sh" <<'DRIVER'
# $1 = cert script path, $2 = certs workdir
source "$1"
C="$2"
mkdir -p "$C"

validate_settings && echo "SETTINGS-OK"

# Invalid settings must be rejected (in a subshell: die exits).
if ( NAMESPACE="Bad_NS!" validate_settings ) 2>/dev/null; then
	echo "NEG-SETTINGS-BAD"
else
	echo "NEG-SETTINGS-OK"
fi

# One OpenSSL config for all fixtures; only operations common to macOS
# LibreSSL and Linux OpenSSL.
cat >"$C/cnf" <<CNF
[req]
prompt = no
distinguished_name = dn
[dn]
CN = kind-compat-test CA
[v3_ca]
basicConstraints = critical, CA:TRUE
keyUsage = critical, keyCertSign, cRLSign
[v3_leaf]
basicConstraints = CA:FALSE
keyUsage = critical, digitalSignature, keyEncipherment
extendedKeyUsage = serverAuth
subjectAltName = DNS:${SAN_SHORT}, DNS:${SAN_LONG}
[v3_leaf_short_only]
basicConstraints = CA:FALSE
keyUsage = critical, digitalSignature, keyEncipherment
extendedKeyUsage = serverAuth
subjectAltName = DNS:${SAN_SHORT}
[v3_ca_as_leaf]
basicConstraints = critical, CA:TRUE
keyUsage = critical, keyCertSign, cRLSign
extendedKeyUsage = serverAuth
subjectAltName = DNS:${SAN_SHORT}, DNS:${SAN_LONG}
CNF

openssl genrsa -out "$C/ca.key" 2048 >/dev/null 2>&1
openssl req -new -x509 -key "$C/ca.key" -out "$C/ca.crt" -days 90 \
	-config "$C/cnf" -extensions v3_ca >/dev/null 2>&1
openssl genrsa -out "$C/tls.key" 2048 >/dev/null 2>&1
openssl req -new -key "$C/tls.key" -out "$C/tls.csr" -config "$C/cnf" \
	-subj "/CN=kind-compat-test" >/dev/null 2>&1
openssl x509 -req -in "$C/tls.csr" -CA "$C/ca.crt" -CAkey "$C/ca.key" \
	-CAcreateserial -out "$C/tls.crt" -days 30 -extfile "$C/cnf" \
	-extensions v3_leaf >/dev/null 2>&1

# A leaf whose SAN list holds only the short Service DNS name.
openssl req -new -key "$C/tls.key" -out "$C/short.csr" -config "$C/cnf" \
	-subj "/CN=kind-compat-test" >/dev/null 2>&1
openssl x509 -req -in "$C/short.csr" -CA "$C/ca.crt" -CAkey "$C/ca.key" \
	-CAcreateserial -out "$C/short.crt" -days 30 -extfile "$C/cnf" \
	-extensions v3_leaf_short_only >/dev/null 2>&1

# A CA:TRUE certificate with serverAuth and both SANs: usable as a chain
# but never acceptable as a serving leaf.
openssl genrsa -out "$C/caleaf.key" 2048 >/dev/null 2>&1
openssl req -new -key "$C/caleaf.key" -out "$C/caleaf.csr" -config "$C/cnf" \
	-subj "/CN=kind-compat-test" >/dev/null 2>&1
openssl x509 -req -in "$C/caleaf.csr" -CA "$C/ca.crt" -CAkey "$C/ca.key" \
	-CAcreateserial -out "$C/caleaf.crt" -days 30 -extfile "$C/cnf" \
	-extensions v3_ca_as_leaf >/dev/null 2>&1

# An unrelated private key.
openssl genrsa -out "$C/wrong.key" 2048 >/dev/null 2>&1

if validate_pair "$C/ca.crt" "$C/tls.crt" "$C/tls.key"; then
	echo "PAIR-GOOD-OK"
else
	echo "PAIR-GOOD-BAD"
	echo "  reason: ${PAIR_ERROR}"
fi

if validate_pair "$C/ca.crt" "$C/tls.crt" "$C/wrong.key"; then
	echo "PAIR-WRONGKEY-BAD"
else
	echo "PAIR-WRONGKEY-OK"
	echo "  reason: ${PAIR_ERROR}"
fi

if validate_pair "$C/ca.crt" "$C/short.crt" "$C/tls.key"; then
	echo "PAIR-SHORTSAN-BAD"
else
	echo "PAIR-SHORTSAN-OK"
	echo "  reason: ${PAIR_ERROR}"
fi

if validate_pair "$C/ca.crt" "$C/caleaf.crt" "$C/caleaf.key"; then
	echo "PAIR-CALEAF-BAD"
else
	echo "PAIR-CALEAF-OK"
	echo "  reason: ${PAIR_ERROR}"
fi

# Bounded SAN matching: a leaf listing only the short name satisfies the
# short check but never the long one.
if cert_has_dns_san "$C/tls.crt" "$SAN_SHORT"; then echo "SAN-BOTH-SHORT-OK"; else echo "SAN-BOTH-SHORT-BAD"; fi
if cert_has_dns_san "$C/tls.crt" "$SAN_LONG"; then echo "SAN-BOTH-LONG-OK"; else echo "SAN-BOTH-LONG-BAD"; fi
if cert_has_dns_san "$C/short.crt" "$SAN_SHORT"; then echo "SAN-SHORTONLY-SHORT-OK"; else echo "SAN-SHORTONLY-SHORT-BAD"; fi
if cert_has_dns_san "$C/short.crt" "$SAN_LONG"; then echo "SAN-SHORTONLY-LONG-BAD"; else echo "SAN-SHORTONLY-LONG-OK"; fi
DRIVER

# ---------------------------------------------------------------------------
# Installer: settings, prepare, and annotated apply files
# ---------------------------------------------------------------------------

echo "== install-openshift-crds.sh: baked settings"
cat >"$WORK/driver-settings.sh" <<'DRIVER'
# $1 = installer path
source "$1"
printf 'KIND_CLUSTER_NAME=%s\nKIND_VERSION=%s\nOWNER_ANNOTATION=%s\nFIELD_MANAGER=%s\n' \
	"$KIND_CLUSTER_NAME" "$KIND_VERSION" "$OWNER_ANNOTATION" "$FIELD_MANAGER"
printf 'MODULES=%s\n' "$(printf '%s' "$CRD_MODULES" | tr '\n' ';')"
printf 'SELECTED=%s\n' "$(printf '%s' "$SELECTED_RESOURCES" | tr '\n' ';')"
printf 'SHIPPED=%s\n' "$(printf '%s' "$SHIPPED_MANIFESTS" | tr '\n' ';')"
printf 'SYNTHETIC=%s\n' "$SYNTHETIC_RESOURCES"
DRIVER
SETTINGS_OUT="$(bash "$WORK/driver-settings.sh" "$INSTALLER" 2>"$WORK/settings.err")" || {
	bad "could not source the installer: $(cat "$WORK/settings.err")"
}
assert_eq "cluster name" "feast-module-operator-e2e" "$(printf '%s\n' "$SETTINGS_OUT" | sed -n 's/^KIND_CLUSTER_NAME=//p')"
assert_eq "kind version" "v0.33.0" "$(printf '%s\n' "$SETTINGS_OUT" | sed -n 's/^KIND_VERSION=//p')"
assert_eq "owner annotation" "e2e.feast.dev/owner" "$(printf '%s\n' "$SETTINGS_OUT" | sed -n 's/^OWNER_ANNOTATION=//p')"
assert_eq "field manager" "feast-module-operator-kind-setup" "$(printf '%s\n' "$SETTINGS_OUT" | sed -n 's/^FIELD_MANAGER=//p')"
assert_eq "CRD modules" \
	"openshift-api|github.com/openshift/api|v0.0.0-20261123012947-9ac77f18ba5d;prometheus-monitoring|github.com/prometheus-operator/prometheus-operator/pkg/apis/monitoring|v0.83.0" \
	"$(printf '%s\n' "$SETTINGS_OUT" | sed -n 's/^MODULES=//p')"
assert_eq "selected resources" \
	"openshift-api|config/v1|config.openshift.io_apiservers.yaml|apiservers.config.openshift.io|no;openshift-api|route/v1|route.openshift.io_routes.yaml|routes.route.openshift.io|no;prometheus-monitoring|v1|monitoring.coreos.com_servicemonitors.yaml|servicemonitors.monitoring.coreos.com|no" \
	"$(printf '%s\n' "$SETTINGS_OUT" | sed -n 's/^SELECTED=//p')"
assert_eq "shipped manifest overrides" \
	"openshift-api|apiservers.config.openshift.io|config/v1/zz_generated.crd-manifests/0000_10_config-operator_01_apiservers-Default.crd.yaml;openshift-api|routes.route.openshift.io|route/v1/zz_generated.crd-manifests/routes.crd.yaml" \
	"$(printf '%s\n' "$SETTINGS_OUT" | sed -n 's/^SHIPPED=//p')"
assert_eq "no synthetic stubs" "" "$(printf '%s\n' "$SETTINGS_OUT" | sed -n 's/^SYNTHETIC=//p')"

echo "== install-openshift-crds.sh: prepare (shipped overrides + annotation)"
# prepare copies the shipped manifests over the generated files inside
# GENERATED_DIR (in the real script that directory is private scratch);
# give it a working copy so the pristine generated fixtures stay available
# for the weaker-schema comparison below.
FIXGEN_WORK="${WORK}/fixtures/generated-work"
cp -R "$FIXGEN" "$FIXGEN_WORK"
if bash "$WORK/driver-prepare.sh" "$INSTALLER" "$FIXSCRATCH" "$FIXGEN_WORK" >"$WORK/prepare.out" 2>"$WORK/prepare.err"; then
	ok "prepare completed (validate_baked_settings + prepare_selected_manifests)"
else
	bad "prepare failed: $(cat "$WORK/prepare.err")"
fi
assert_file_contains "prepare reports the apiservers shipped override" "$WORK/prepare.out" "shipped manifest overrides generated output for apiservers.config.openshift.io"
assert_file_contains "prepare reports the routes shipped override" "$WORK/prepare.out" "shipped manifest overrides generated output for routes.route.openshift.io"

for crd in apiservers.config.openshift.io routes.route.openshift.io servicemonitors.monitoring.coreos.com; do
	apply_file="${FIXSCRATCH}/apply/${crd}.yaml"
	if [ -s "$apply_file" ]; then
		ok "apply file prepared for ${crd}"
	else
		bad "apply file missing or empty for ${crd}"
		continue
	fi
	owner="$(yq ".metadata.annotations.\"e2e.feast.dev/owner\"" "$apply_file")"
	assert_eq "apply file for ${crd} carries the owner annotation" "feast-module-operator-e2e" "$owner"
done

# The annotation step must not change the stored spec: the apply file stays
# equivalent to the manifest prepare started from (the shipped fixture for
# the two overrides, the generated fixture for ServiceMonitor).
EQUIV_OUT="$(bash "$WORK/driver-equivalence.sh" "$INSTALLER" \
	"$FIXMOD/config/v1/zz_generated.crd-manifests/0000_10_config-operator_01_apiservers-Default.crd.yaml" \
	"$FIXSCRATCH/apply/apiservers.config.openshift.io.yaml")"
assert_eq "annotated apiservers apply file keeps the shipped spec" "EQUIV-OK" "$EQUIV_OUT"
EQUIV_OUT="$(bash "$WORK/driver-equivalence.sh" "$INSTALLER" \
	"$FIXMOD/route/v1/zz_generated.crd-manifests/routes.crd.yaml" \
	"$FIXSCRATCH/apply/routes.route.openshift.io.yaml")"
assert_eq "annotated routes apply file keeps the shipped spec" "EQUIV-OK" "$EQUIV_OUT"
EQUIV_OUT="$(bash "$WORK/driver-equivalence.sh" "$INSTALLER" \
	"$FIXGEN/prometheus-monitoring_v1/monitoring.coreos.com_servicemonitors.yaml" \
	"$FIXSCRATCH/apply/servicemonitors.monitoring.coreos.com.yaml")"
assert_eq "annotated servicemonitors apply file keeps the generated spec" "EQUIV-OK" "$EQUIV_OUT"

# ---------------------------------------------------------------------------
# Persisted-CRD fixtures derived from the prepared apply files. The
# derivation adds only what a real API server adds (status, metadata
# bookkeeping, a None conversion strategy) and removes fields the
# equivalence check must normalize (the derived names.singular, the
# defaulted versions[].served), so the equivalent fixture proves the
# documented-defaults normalization instead of a trivial byte match.
# ---------------------------------------------------------------------------

make_persisted() {
	# make_persisted <apply-file> <out-json> <owner: own|none|other> <mutate: none|incompatible>
	yq -o=json '.' "$1" | jq --arg owner "$3" --arg mutate "$4" '
		.metadata.annotations["e2e.feast.dev/owner"] = (
			if $owner == "none" then null
			elif $owner == "other" then "another-e2e-cluster"
			else "feast-module-operator-e2e" end)
		| .metadata.resourceVersion = "12345"
		| .metadata.uid = "00000000-0000-0000-0000-000000000001"
		| .metadata.creationTimestamp = "2026-11-26T00:00:00Z"
		| .metadata.generation = 1
		| .metadata.managedFields = [ { "manager": "feast-module-operator-kind-setup", "operation": "Apply" } ]
		| .status = { "conditions": [], "acceptedNames": { "plural": "x", "kind": "X" }, "storedVersions": ["v1"] }
		| .spec.conversion = { "strategy": "None" }
		| del(.spec.names.singular)
		| del(.spec.versions[0].served)
		| if $mutate == "incompatible" then
			.spec.versions[0].schema.openAPIV3Schema.properties.spec.properties.unexpected = { "type": "string" }
		else . end
	' >"$2"
}

APPLY_SM="${FIXSCRATCH}/apply/servicemonitors.monitoring.coreos.com.yaml"
APPLY_API="${FIXSCRATCH}/apply/apiservers.config.openshift.io.yaml"

make_persisted "$APPLY_SM" "$WORK/persisted-equivalent.json" own none
make_persisted "$APPLY_SM" "$WORK/persisted-unowned.json" none none
make_persisted "$APPLY_SM" "$WORK/persisted-other-owner.json" other none
make_persisted "$APPLY_SM" "$WORK/persisted-incompatible.json" own incompatible
printf 'Error from server (Forbidden): not JSON at all\n' >"$WORK/persisted-unreadable.json"
: >"$WORK/persisted-empty.json"

echo "== install-openshift-crds.sh: classification"

classify_result() {
	# classify_result <persisted-json> <apply-file>
	bash "$WORK/driver-classify.sh" "$INSTALLER" "$1" "$2" 2>/dev/null |
		sed -n 's/^DECISION=//p'
}

assert_eq "equivalent owned CRD is reused" "reuse" "$(classify_result "$WORK/persisted-equivalent.json" "$APPLY_SM")"
assert_eq "unowned CRD is refused" "refuse" "$(classify_result "$WORK/persisted-unowned.json" "$APPLY_SM")"
assert_eq "other-owner CRD is refused" "refuse" "$(classify_result "$WORK/persisted-other-owner.json" "$APPLY_SM")"
assert_eq "incompatible owned CRD is refused" "refuse" "$(classify_result "$WORK/persisted-incompatible.json" "$APPLY_SM")"
assert_eq "unreadable CRD is refused" "refuse" "$(classify_result "$WORK/persisted-unreadable.json" "$APPLY_SM")"
assert_eq "empty CRD document is refused" "refuse" "$(classify_result "$WORK/persisted-empty.json" "$APPLY_SM")"

# A CRD of a different generation (the schema-poor generated fixture for
# apiservers) must not be equivalent to the shipped apply file.
EQUIV_OUT="$(bash "$WORK/driver-equivalence.sh" "$INSTALLER" \
	"$FIXGEN/openshift-api_config_v1/config.openshift.io_apiservers.yaml" "$APPLY_API")"
assert_eq "generated (weaker) apiservers schema is not equivalent to the shipped one" "EQUIV-DIFF" "$EQUIV_OUT"
# ---------------------------------------------------------------------------
# Ordering: the whole set is classified before any apply; any refusal (or
# read failure) means zero applies, including when the failing resource is
# the last in the selected set.
# ---------------------------------------------------------------------------

run_order() {
	# run_order <existing-dir> <out-file> <err-file>; also sets ORDER_LOG
	ORDER_LOG="$WORK/order-$(basename "$1").log"
	: >"$ORDER_LOG"
	bash "$WORK/driver-order.sh" "$INSTALLER" "$FIXSCRATCH" "$1" "$ORDER_LOG" >"$2" 2>"$3"
}

echo "== install-openshift-crds.sh: all-set-before-write ordering"

# S1: all three CRDs absent -> three applies, three waits.
EXIST_S1="$WORK/existing-absent"
mkdir -p "$EXIST_S1"
run_order "$EXIST_S1" "$WORK/s1.out" "$WORK/s1.err" && ok "S1 (all absent) succeeds" || bad "S1 (all absent) failed: $(cat "$WORK/s1.err")"
assert_eq "S1: three CRDs applied" "3" "$(log_count '^kctl: apply' "$ORDER_LOG")"
assert_eq "S1: three Established waits" "3" "$(log_count '^kctl: wait' "$ORDER_LOG")"
assert_eq "S1: no existing-CRD reads" "0" "$(log_count '^kctl: get crd ' "$ORDER_LOG")"
assert_file_contains "S1: preflight counts the full set" "$WORK/s1.out" "3 CRD(s) to apply, 0 existing owned definition(s) to reuse"

# S2: the last selected CRD exists unowned -> refusal, zero applies.
EXIST_S2="$WORK/existing-unowned-last"
mkdir -p "$EXIST_S2"
cp "$WORK/persisted-unowned.json" "$EXIST_S2/servicemonitors.monitoring.coreos.com.json"
run_order "$EXIST_S2" "$WORK/s2.out" "$WORK/s2.err" && bad "S2 (unowned last entry) unexpectedly succeeded" || ok "S2 (unowned last entry) fails closed"
assert_eq "S2: zero applies after a last-entry refusal" "0" "$(log_count '^kctl: apply' "$ORDER_LOG")"
assert_eq "S2: the refusing CRD was still read and classified" "1" "$(log_count '^kctl: get crd servicemonitors.monitoring.coreos.com' "$ORDER_LOG")"
if grep -qF "No CRDs were applied" "$WORK/s2.err"; then
	ok "S2: failure states that no CRDs were applied"
else
	bad "S2: failure does not state that no CRDs were applied: $(cat "$WORK/s2.err")"
fi

# S3: one equivalent owned CRD -> reused without rewriting, others applied.
EXIST_S3="$WORK/existing-equivalent-first"
mkdir -p "$EXIST_S3"
make_persisted "$APPLY_API" "$EXIST_S3/apiservers.config.openshift.io.json" own none
run_order "$EXIST_S3" "$WORK/s3.out" "$WORK/s3.err" && ok "S3 (equivalent owned) succeeds" || bad "S3 (equivalent owned) failed: $(cat "$WORK/s3.err")"
assert_eq "S3: only the two missing CRDs are applied" "2" "$(log_count '^kctl: apply' "$ORDER_LOG")"
assert_eq "S3: the reused CRD is not applied" "0" "$(log_count "kctl: apply.*apiservers.config.openshift.io" "$ORDER_LOG")"
assert_file_contains "S3: the reused CRD is reported as reused" "$WORK/s3.out" "reusing without rewriting: apiservers.config.openshift.io"
assert_file_contains "S3: preflight counts one reuse" "$WORK/s3.out" "2 CRD(s) to apply, 1 existing owned definition(s) to reuse"

# S4: a listed CRD cannot be read -> refusal, zero applies.
EXIST_S4="$WORK/existing-readfail-last"
mkdir -p "$EXIST_S4"
: >"$EXIST_S4/servicemonitors.monitoring.coreos.com.readfail"
run_order "$EXIST_S4" "$WORK/s4.out" "$WORK/s4.err" && bad "S4 (unreadable last entry) unexpectedly succeeded" || ok "S4 (unreadable last entry) fails closed"
assert_eq "S4: zero applies after a read failure" "0" "$(log_count '^kctl: apply' "$ORDER_LOG")"
if grep -qF "could not read the existing CRD" "$WORK/s4.err"; then
	ok "S4: failure reports the read error"
else
	bad "S4: failure does not report the read error: $(cat "$WORK/s4.err")"
fi

# S5: the first selected CRD exists but is incompatible -> refusal, zero applies.
EXIST_S5="$WORK/existing-incompatible-first"
mkdir -p "$EXIST_S5"
make_persisted "$APPLY_API" "$EXIST_S5/apiservers.config.openshift.io.json" own incompatible
run_order "$EXIST_S5" "$WORK/s5.out" "$WORK/s5.err" && bad "S5 (incompatible first entry) unexpectedly succeeded" || ok "S5 (incompatible first entry) fails closed"
assert_eq "S5: zero applies after a first-entry refusal" "0" "$(log_count '^kctl: apply' "$ORDER_LOG")"
if grep -qF "stored spec differs" "$WORK/s5.err"; then
	ok "S5: failure reports the incompatibility"
else
	bad "S5: failure does not report the incompatibility: $(cat "$WORK/s5.err")"
fi

# S6: an other-owner CRD in the middle of the set -> refusal, zero applies.
EXIST_S6="$WORK/existing-other-owner-middle"
mkdir -p "$EXIST_S6"
make_persisted "$FIXSCRATCH/apply/routes.route.openshift.io.yaml" "$EXIST_S6/routes.route.openshift.io.json" other none
run_order "$EXIST_S6" "$WORK/s6.out" "$WORK/s6.err" && bad "S6 (other-owner middle entry) unexpectedly succeeded" || ok "S6 (other-owner middle entry) fails closed"
assert_eq "S6: zero applies after a middle-entry refusal" "0" "$(log_count '^kctl: apply' "$ORDER_LOG")"
if grep -qF "names a different cluster" "$WORK/s6.err"; then
	ok "S6: failure reports the different owner"
else
	bad "S6: failure does not report the different owner: $(cat "$WORK/s6.err")"
fi

# ---------------------------------------------------------------------------
# Certificate script
# ---------------------------------------------------------------------------

echo "== setup-service-certs.sh: baked settings"
cat >"$WORK/driver-cert-settings.sh" <<'DRIVER'
# $1 = cert script path
source "$1"
printf 'NAMESPACE=%s\nSERVICE_NAME=%s\nTLS_SECRET_NAME=%s\nCA_CONFIGMAP_NAME=%s\nCA_CONFIGMAP_KEY=%s\nCLUSTER_DNS_DOMAIN=%s\nKIND_CLUSTER_NAME=%s\nKIND_VERSION=%s\n' \
	"$NAMESPACE" "$SERVICE_NAME" "$TLS_SECRET_NAME" "$CA_CONFIGMAP_NAME" "$CA_CONFIGMAP_KEY" "$CLUSTER_DNS_DOMAIN" "$KIND_CLUSTER_NAME" "$KIND_VERSION"
printf 'SAN_SHORT=%s\nSAN_LONG=%s\n' "$SAN_SHORT" "$SAN_LONG"
DRIVER
CERT_SETTINGS="$(bash "$WORK/driver-cert-settings.sh" "$CERT_SCRIPT" 2>"$WORK/cert-settings.err")" || {
	bad "could not source the cert script: $(cat "$WORK/cert-settings.err")"
}
assert_eq "namespace" "opendatahub-feast-system" "$(printf '%s\n' "$CERT_SETTINGS" | sed -n 's/^NAMESPACE=//p')"
assert_eq "service name" "feast-operator-controller-manager-metrics-service" "$(printf '%s\n' "$CERT_SETTINGS" | sed -n 's/^SERVICE_NAME=//p')"
assert_eq "TLS secret name" "controller-manager-metrics-tls" "$(printf '%s\n' "$CERT_SETTINGS" | sed -n 's/^TLS_SECRET_NAME=//p')"
assert_eq "CA configmap name" "openshift-service-ca.crt" "$(printf '%s\n' "$CERT_SETTINGS" | sed -n 's/^CA_CONFIGMAP_NAME=//p')"
assert_eq "CA configmap key" "service-ca.crt" "$(printf '%s\n' "$CERT_SETTINGS" | sed -n 's/^CA_CONFIGMAP_KEY=//p')"
assert_eq "cluster DNS domain" "cluster.local" "$(printf '%s\n' "$CERT_SETTINGS" | sed -n 's/^CLUSTER_DNS_DOMAIN=//p')"
assert_eq "cert cluster name" "feast-module-operator-e2e" "$(printf '%s\n' "$CERT_SETTINGS" | sed -n 's/^KIND_CLUSTER_NAME=//p')"
assert_eq "cert kind version" "v0.33.0" "$(printf '%s\n' "$CERT_SETTINGS" | sed -n 's/^KIND_VERSION=//p')"
assert_eq "short SAN" "feast-operator-controller-manager-metrics-service.opendatahub-feast-system.svc" "$(printf '%s\n' "$CERT_SETTINGS" | sed -n 's/^SAN_SHORT=//p')"
assert_eq "long SAN" "feast-operator-controller-manager-metrics-service.opendatahub-feast-system.svc.cluster.local" "$(printf '%s\n' "$CERT_SETTINGS" | sed -n 's/^SAN_LONG=//p')"

echo "== setup-service-certs.sh: settings and pair validation"
CERTS_OUT="$(bash "$WORK/driver-certs.sh" "$CERT_SCRIPT" "$WORK/certs" 2>"$WORK/certs.err")" || {
	bad "cert driver failed: $(cat "$WORK/certs.err")"
}
cert_line() { printf '%s\n' "$CERTS_OUT" | grep -m1 "^$1" || true; }
assert_eq "baked settings validate" "SETTINGS-OK" "$(cert_line 'SETTINGS-OK')"
assert_eq "invalid settings are rejected" "NEG-SETTINGS-OK" "$(cert_line 'NEG-SETTINGS-OK')"
assert_eq "fresh CA-signed pair validates" "PAIR-GOOD-OK" "$(cert_line 'PAIR-GOOD')"
assert_eq "mismatched key is rejected" "PAIR-WRONGKEY-OK" "$(cert_line 'PAIR-WRONGKEY')"
assert_eq "missing long SAN is rejected" "PAIR-SHORTSAN-OK" "$(cert_line 'PAIR-SHORTSAN')"
assert_eq "CA certificate as leaf is rejected" "PAIR-CALEAF-OK" "$(cert_line 'PAIR-CALEAF')"
assert_eq "both-SAN leaf matches the short SAN" "SAN-BOTH-SHORT-OK" "$(cert_line 'SAN-BOTH-SHORT')"
assert_eq "both-SAN leaf matches the long SAN" "SAN-BOTH-LONG-OK" "$(cert_line 'SAN-BOTH-LONG')"
assert_eq "short-only leaf matches the short SAN" "SAN-SHORTONLY-SHORT-OK" "$(cert_line 'SAN-SHORTONLY-SHORT')"
assert_eq "short-only leaf does not match the long SAN" "SAN-SHORTONLY-LONG-OK" "$(cert_line 'SAN-SHORTONLY-LONG')"

# ---------------------------------------------------------------------------
# Summary
# ---------------------------------------------------------------------------

echo
echo "kind-compatibility-test: ${PASS} passed, ${FAIL} failed"
[ "$FAIL" -eq 0 ] || exit 1
exit 0
